CREATE FUNCTION public.pm_guard_closed() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p uuid; s text; BEGIN IF TG_TABLE_NAME='pm_projects' THEN p:=OLD.id; ELSE p:=COALESCE(NEW.project_id,OLD.project_id); END IF; SELECT status INTO s FROM public.pm_projects WHERE id=p; IF TG_TABLE_NAME='pm_projects' AND TG_OP='UPDATE' THEN IF OLD.status IN ('concluido','cancelado') THEN RAISE EXCEPTION 'Projeto encerrado não pode ser alterado'; END IF; IF NEW.status IS DISTINCT FROM OLD.status AND NOT public.pm_can_manage(OLD.id) THEN RAISE EXCEPTION 'Somente gestores alteram a situação'; END IF; ELSE IF s IN ('concluido','cancelado') THEN RAISE EXCEPTION 'Projeto encerrado não pode ser alterado'; END IF; END IF; IF TG_TABLE_NAME='pm_tasks' AND TG_OP<>'DELETE' THEN IF NEW.milestone AND NEW.duration<>0 OR NOT NEW.milestone AND NEW.duration<1 THEN RAISE EXCEPTION 'Marcos têm duração zero e atividades têm duração positiva'; END IF; END IF; IF TG_TABLE_NAME='pm_allocations' AND TG_OP='UPDATE' AND (NEW.task_id IS DISTINCT FROM OLD.task_id OR NEW.resource_id IS DISTINCT FROM OLD.resource_id OR NEW.unit_rate IS DISTINCT FROM OLD.unit_rate) THEN RAISE EXCEPTION 'A tarefa, o recurso e a taxa registrada da alocação são preservados'; END IF; IF TG_TABLE_NAME='pm_phases' AND TG_OP='UPDATE' AND (NEW.accepted_at IS DISTINCT FROM OLD.accepted_at OR NEW.accepted_by IS DISTINCT FROM OLD.accepted_by) AND NOT public.pm_can_manage(NEW.project_id) THEN RAISE EXCEPTION 'Somente gestores aceitam entregáveis'; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER pm_project_closed BEFORE UPDATE ON public.pm_projects FOR EACH ROW EXECUTE FUNCTION public.pm_guard_closed();
CREATE TRIGGER pm_task_closed BEFORE INSERT OR UPDATE OR DELETE ON public.pm_tasks FOR EACH ROW EXECUTE FUNCTION public.pm_guard_closed();
CREATE TRIGGER pm_phase_closed BEFORE INSERT OR UPDATE OR DELETE ON public.pm_phases FOR EACH ROW EXECUTE FUNCTION public.pm_guard_closed();
CREATE TRIGGER pm_resource_closed BEFORE INSERT OR UPDATE OR DELETE ON public.pm_resources FOR EACH ROW EXECUTE FUNCTION public.pm_guard_closed();
CREATE TRIGGER pm_allocation_closed BEFORE INSERT OR UPDATE OR DELETE ON public.pm_allocations FOR EACH ROW EXECUTE FUNCTION public.pm_guard_closed();
CREATE TRIGGER pm_member_closed BEFORE INSERT OR UPDATE OR DELETE ON public.pm_members FOR EACH ROW EXECUTE FUNCTION public.pm_guard_closed();
CREATE TRIGGER pm_dependency_closed BEFORE INSERT OR UPDATE OR DELETE ON public.pm_dependencies FOR EACH ROW EXECUTE FUNCTION public.pm_guard_closed();
CREATE TRIGGER pm_baseline_closed BEFORE INSERT ON public.pm_baselines FOR EACH ROW EXECUTE FUNCTION public.pm_guard_closed();
CREATE INDEX pm_tasks_project_idx ON public.pm_tasks(project_id); CREATE INDEX pm_allocations_project_idx ON public.pm_allocations(project_id); CREATE INDEX pm_logs_project_idx ON public.pm_logs(project_id,created_at DESC);